<template><div class="layout"><header class="header"><router-link to="/app" class="brand"><span class="brand-mark">A</span><span>AutoOps</span><small>OPS CONTROL ROOM</small></router-link><div class="header-right"><span class="connection"><i></i>Kubernetes 已连接</span><n-tag type="success" size="small">MINIKUBE</n-tag><n-button quaternary circle :loading="store.loading" @click="refresh"><template #icon><n-icon><RefreshOutline/></n-icon></template></n-button><span class="sync-time">{{store.lastRefresh?'刚刚同步':'等待同步'}}</span></div></header><div class="layout-body"><aside :class="['sidebar',{collapsed}]"><div class="sidebar-caption">OPERATIONS</div><div class="sidebar-menu"><n-menu :value="active" :options="options" :collapsed="collapsed" :collapsed-width="70" @update:value="go"/></div><div class="sidebar-footer"><n-button quaternary circle @click="collapsed=!collapsed"><template #icon><n-icon><ChevronBackOutline v-if="!collapsed"/><ChevronForwardOutline v-else/></n-icon></template></n-button></div></aside><main class="main"><router-view/></main></div></div></template>
<script setup>import{h,ref,computed,onMounted,onUnmounted}from'vue';import{useRoute,useRouter}from'vue-router';import{NIcon,useNotification}from'naive-ui';import{HomeOutline,WarningOutline,GitNetworkOutline,BookOutline,RefreshOutline,ChevronBackOutline,ChevronForwardOutline}from'@vicons/ionicons5';import{useDashboardStore}from'@/stores/dashboard';const route=useRoute(),router=useRouter(),store=useDashboardStore(),collapsed=ref(false),notification=useNotification();const items=[['Dashboard','运维工作台','/app',HomeOutline],['Background','后台任务','/app/background',WarningOutline],['Incidents','故障排查','/app/incidents',WarningOutline],['Cluster','集群观测','/app/cluster',GitNetworkOutline],['Knowledge','维护文档','/app/knowledge',BookOutline]],options=items.map(([key,label,path,icon])=>({key,label,icon:()=>h(NIcon,null,{default:()=>h(icon)})})),active=computed(()=>route.name||'Dashboard');function go(key){const item=items.find(x=>x[0]===key);if(item)router.push(item[2])}async function refresh(){try{await store.refresh()}catch(e){notification.error({title:'刷新失败',content:e.message})}}let timer;onMounted(()=>{store.refresh();timer=setInterval(()=>store.refresh(),30000)});onUnmounted(()=>clearInterval(timer))</script>
